var webinarwrapper=".webinar-series";(function($){$(webinarwrapper+" .tab").on("click",function(){$("#video-iframe").attr("src","");$("#video-iframe").hide();$(webinarwrapper+" .tab").removeClass("active");$(this).addClass("active");var id=$(this).data("id");$(webinarwrapper+" .panel").removeClass("active");$(webinarwrapper+" #panel-"+id).addClass("active")});$(".panelist").on("click",function(event){if(event.target.getAttribute("class")!="bio"){$(".bio",this).addClass("active")}});$(webinarwrapper+" .bio").on("click",function(){$(webinarwrapper+" .bio").removeClass("active")});$(webinarwrapper+" .watch-video").on("click",function(event){event.preventDefault();$(webinarwrapper+" .bio").removeClass("active");var url=$(this).attr("href");$("#video-iframe").attr("src",url);$("#video-iframe").show();$('html, body').animate({scrollTop:$("#video-iframe").offset().top-125},1000,function(){$(webinarwrapper+" .bio").removeClass("active")})})})(jQuery)